package com.shengxu.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.shengxu.dto.MusicDtos.*; import com.shengxu.entity.*; import com.shengxu.mapper.*; import org.springframework.stereotype.Service;
@Service public class CreditService { private final UserCreditMapper credits;private final CreditRecordMapper records;public CreditService(UserCreditMapper c,CreditRecordMapper r){credits=c;records=r;}public CreditView balance(Long uid){UserCredit c=credits.selectOne(new LambdaQueryWrapper<UserCredit>().eq(UserCredit::getUserId,uid));return new CreditView(c.getBalance());}public PageView<CreditRecordView> records(Long uid,long page,long size){var p=records.selectPage(new Page<>(page,Math.min(size,50)),new LambdaQueryWrapper<CreditRecord>().eq(CreditRecord::getUserId,uid).orderByDesc(CreditRecord::getCreatedAt));return new PageView<>(p.getRecords().stream().map(r->new CreditRecordView(r.getId(),r.getRecordType(),r.getAmount(),r.getBalanceAfter(),r.getRemark(),r.getCreatedAt())).toList(),p.getTotal(),p.getCurrent(),p.getSize());}}

